-- V4：人审否决的永久抑制项（P1，设计见 docs/sensitive-data-design.md §7.2）
--
-- 与 MySQL 侧同一张表、同一份实体派生，只是方言不同：自增列是
-- generated by default as identity、注释是独立的 comment on ... is '...'。
-- 内容与 sql/schema-postgres.sql 里那份全量快照逐字一致，改结构仍然只改实体，
-- 再依次跑 ./scripts/gen-postgres-ddl.sh 与 scripts/gen-flyway-baseline.py。
--
-- 为什么需要这张表、为什么键是 (column_ref_hash, type_code)，见 MySQL 那份开头的说明
-- （两份共用一份理由，不各写一遍——两个版本对同一件事的措辞漂移，比没有注释更坏）。

create table lakehouse_sensitivity_suppression (
        enabled_flag boolean not null,
        created_at bigint,
        decided_at bigint,
        finding_id bigint,
        id bigint generated by default as identity,
        updated_at bigint,
        catalog_name varchar(64) not null,
        column_ref_hash varchar(64) not null,
        type_code varchar(64) not null,
        reason varchar(512),
        table_name varchar(512) not null,
        column_name varchar(255) not null,
        created_by varchar(255),
        database_name varchar(255) not null,
        decided_by varchar(255),
        owner varchar(255),
        updated_by varchar(255),
        primary key (id),
        constraint uk_sensitivity_suppression unique (column_ref_hash, type_code)
    );

comment on table lakehouse_sensitivity_suppression is
    '人审否决的永久抑制项（按列哈希 + 类型记，重扫不再自动打标）';

comment on column lakehouse_sensitivity_suppression.enabled_flag is
    '是否仍生效；解禁置 false，不删行';

comment on column lakehouse_sensitivity_suppression.created_at is
    '创建时刻（epoch 毫秒）';

comment on column lakehouse_sensitivity_suppression.decided_at is
    '否决时刻（epoch 毫秒）';

comment on column lakehouse_sensitivity_suppression.finding_id is
    '来源 finding 的 id（溯源用，可空）';

comment on column lakehouse_sensitivity_suppression.id is
    '自增主键';

comment on column lakehouse_sensitivity_suppression.updated_at is
    '最后更新时刻（epoch 毫秒）';

comment on column lakehouse_sensitivity_suppression.catalog_name is
    'catalog 名';

comment on column lakehouse_sensitivity_suppression.column_ref_hash is
    'catalog.db.table.column 的 SHA-256（列改名后哈希变，抑制项自动失效）';

comment on column lakehouse_sensitivity_suppression.type_code is
    '被否决的敏感类型';

comment on column lakehouse_sensitivity_suppression.reason is
    '否决理由（人审备注）';

comment on column lakehouse_sensitivity_suppression.table_name is
    '表名';

comment on column lakehouse_sensitivity_suppression.column_name is
    '列名';

comment on column lakehouse_sensitivity_suppression.created_by is
    '创建者主体名（写入前已按列宽归一化）';

comment on column lakehouse_sensitivity_suppression.database_name is
    '库名';

comment on column lakehouse_sensitivity_suppression.decided_by is
    '否决人主体名';

comment on column lakehouse_sensitivity_suppression.owner is
    '记录归属主体（展示与过滤用，不参与授权判定）';

comment on column lakehouse_sensitivity_suppression.updated_by is
    '最后更新者主体名（写入前已按列宽归一化）';

create index ix_sensitivity_suppression_catalog
       on lakehouse_sensitivity_suppression (catalog_name);
